## Submitted testbench
```systemverilog
module tb;
  // -------------------------------------------------
  // Clock and reset
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz
  localparam int PRESCALE_VAL = 1; // use minimum prescale for simplicity
  localparam int BIT_TIME = 8 * PRESCALE_VAL; // 8 cycles per bit

  reg clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  reg rst = 0;
  initial begin
    #(CLK_PERIOD*2) rst = 1'b1;
    #(CLK_PERIOD*2) rst = 1'b0;
    #(CLK_PERIOD*2);
  end

  // -------------------------------------------------
  // Configuration and DUT ports
  // -------------------------------------------------
  reg [15:0] prescale = PRESCALE_VAL;
  reg rxd = 1'b1;

  wire [7:0] m_axis_tdata;
  wire       m_axis_tvalid;
  wire       busy;
  wire       overrun_error;
  wire       frame_error;

  // -------------------------------------------------
  // Instantiate the receiver (default DATA_WIDTH = 8)
  // -------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(1'b1),          // always ready to accept
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale)
  );

  // -------------------------------------------------
  // Task: transmit one byte on rxd, optionally inserting a
  //       two‑edge glitch on a selected data bit.
  // -------------------------------------------------
  task automatic send_frame(
    input byte unsigned data,
    input int      glitch_bit_idx,
    input bit      has_glitch
  );
    int cycles = BIT_TIME;

    // start bit
    rxd = 1'b0;
    repeat (cycles) @(negedge clk);

    // data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      bit orig = data[i];
      bit opp  = orig ^ 1'b1;
      if (has_glitch && (i == glitch_bit_idx)) begin
        // original for (cycles-2) clocks
        repeat (cycles-2) begin
          rxd = orig;
          @(negedge clk);
        end
        // toggle to opposite (first edge)
        rxd = opp;
        @(negedge clk);
        // toggle back to original (second edge)
        rxd = orig;
        @(negedge clk);
      end else begin
        repeat (cycles) begin
          rxd = orig;
          @(negedge clk);
        end
      end
    end

    // stop bit
    rxd = 1'b1;
    repeat (cycles) @(negedge clk);
  endtask

  // -------------------------------------------------
  // Stimulus
  // -------------------------------------------------
  initial begin
    // small start‑up delay
    repeat (10) @(negedge clk);

    // First frame: 0xA5 with a glitch on bit index 2
    send_frame(8'hA5, 2, 1);

    // Inter‑frame gap (as in the baseline regression)
    #2000;

    // Second frame: 0x5A, no glitch
    send_frame(8'h5A, 0, 0);

    // Allow enough time for the coverage property to be evaluated
    repeat (200) @(negedge clk);

    // End simulation – $finish is required
    $finish;
  end
endmodule
